import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class Period_normalizedStandard_TriageGen1Test {





    @Test
    public void testNormalizedStandard_WithYearsOnly() {
        // Period: 1 year, 2 months (total 14 months)
        // Target: PeriodType that only supports years
        Period period = new Period(1, 2, 0, 0, 0, 0, 0, 0, PeriodType.standard());
        Period result = period.normalizedStandard(PeriodType.years());

        // 14 months / 12 = 1 year, remainder 2 months. 
        // Since type only supports years, the 2 months are discarded via the withYears logic
        // However, the code checks if totalMonths != 0 at the end.
        // Let's use a case where it divides perfectly to avoid UnsupportedOperationException
        Period perfectYearPeriod = new Period(1, 0, 0, 0, 0, 0, 0, 0, PeriodType.standard());
        Period yearResult = perfectYearPeriod.normalizedStandard(PeriodType.years());
        assertEquals(1, yearResult.getYears());
        assertEquals(0, yearResult.getMonths());
    }










}

