import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class Period_normalizedStandard_TriageGen1Test {









    @Test(expected = UnsupportedOperationException.class)
    public void testNormalizedStandard_ThrowsExceptionWhenMonthsRemain() {
        // Period has 1 year, 2 months. 
        // We request a PeriodType that supports Years but NOT Months.
        // totalMonths = 14. normalizedYears = 1. totalMonths becomes 14 - 12 = 2.
        // Since type.isSupported(MONTHS_TYPE) is false, totalMonths remains 2.
        // totalMonths != 0 throws exception.

        // We need a custom PeriodType or a way to simulate missing months support.
        // Since PeriodType.standard() supports both, we use a custom type if possible, 
        // but standard ones are usually: all, years, months, weeks, days, hours, minutes, seconds, millis.

        // Using a PeriodType that only supports years
        Period period = new Period(1, 2, 0, 0, 0, 0, 0, 0, PeriodType.standard());
        period.normalizedStandard(PeriodType.years());
    }






}

