        // Test that long overflow is handled (as per comment in code)
        // 1000000 days
        long millis = 1000000L * DateTimeConstants.MILLIS_PER_DAY;
        Period period = new Period(millis, PeriodType.standard());
        Period result = period.normalizedStandard(PeriodType.standard());
